select
  PRESC_DATE, PRESC_NO, ITEM_NO, DRUG_CODE, DRUG_SPEC, DRUG_NAME
from drug_presc_detail

    
        and PRESC_DATE = #{prescDate}
    
    
        and PRESC_NO = #{prescNo}
    
    
        and ITEM_NO = #{itemNo}
    
    
        and DRUG_CODE = #{drugCode}
    
    
        and DRUG_SPEC = #{drugSpec}
    
    
        and DRUG_NAME = #{drugName}
    

limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from drug_presc_detail

    
        and PRESC_DATE = #{prescDate}
    
    
        and PRESC_NO = #{prescNo}
    
    
        and ITEM_NO = #{itemNo}
    
    
        and DRUG_CODE = #{drugCode}
    
    
        and DRUG_SPEC = #{drugSpec}
    
    
        and DRUG_NAME = #{drugName}

select count(1)
from drug_presc_detail

    
        and date_format(PRESC_DATE,'%Y-%m-%d') = #{params.recordingDate}

select
PRESC_DATE, PRESC_NO, ITEM_NO, DRUG_CODE, DRUG_SPEC, DRUG_NAME
from drug_presc_detail

    
